begin;
alter table public.nexus_city_placements drop constraint nexus_city_placements_x_check,drop constraint nexus_city_placements_z_check,
 add constraint nexus_city_placements_x_check check(x between -1000 and 1000),add constraint nexus_city_placements_z_check check(z between -1000 and 1000);
alter table public.nexus_city_collectible_displays drop constraint nexus_city_collectible_displays_x_check,drop constraint nexus_city_collectible_displays_z_check,
 add constraint nexus_city_collectible_displays_x_check check(x between -1000 and 1000),add constraint nexus_city_collectible_displays_z_check check(z between -1000 and 1000);
create function public.city3b_map_half(p_city jsonb) returns integer language sql immutable set search_path='' as $$ select case when p_city->>'map_extent'='1000' then 1000 else 500 end $$;
revoke all on function public.city3b_map_half(jsonb) from public,anon,authenticated;
grant execute on function public.city3b_map_half(jsonb) to service_role;

-- Add land around existing cities, preserving coordinates, scenery, wallet and progress.
update public.nexus_cities set city=jsonb_set(coalesce(city,'{}'),'{map_extent}','1000'),revision=revision+1,updated_at=now();
create or replace function public.city3b_large_map_defaults() returns trigger language plpgsql security invoker set search_path='' as $$
begin new.city:=coalesce(new.city,'{}'::jsonb)||jsonb_build_object('map_extent',1000,'core_half',95);return new;end $$;

-- Only spatial constants change; economy and object-count limits stay intact.
do $spatial$
declare signature text;before text;body text;
begin
 foreach signature in array array['nexus_city_place_v2(uuid,text,integer,integer,smallint,uuid)','nexus_city_move_v2(uuid,uuid,integer,integer,smallint,uuid)','city3b_validate_parcel()','nexus_city_plan_roads(uuid,jsonb)','nexus_city_plan_terrain(uuid,jsonb,jsonb)','nexus_city_campaign_metrics(uuid)','nexus_city_plan_networks(uuid,jsonb,jsonb)','nexus_city_plan_signals(uuid,jsonb,jsonb)'] loop
  if to_regprocedure('public.'||signature) is null then raise exception 'Missing map dependency: %',signature;end if;
  before:=pg_get_functiondef(('public.'||signature)::regprocedure);body:=before;
  body:=replace(body,'half=500;','half=public.city3b_map_half(c.city);');
  body:=replace(body,'half:=500;','half:=public.city3b_map_half(c.city);');
  body:=replace(body,'>500 then raise exception ''Route hors du terrain''','>public.city3b_map_half(c.city) then raise exception ''Route hors du terrain''');
  body:=replace(body,'abs(x)+w/2>500','abs(x)+w/2>public.city3b_map_half(c.city)');
  body:=replace(body,'abs(x)>500 or abs(z)>500','abs(x)>public.city3b_map_half(c.city) or abs(z)>public.city3b_map_half(c.city)');
  body:=replace(body,'greatest(abs(x1),abs(x2),abs(z1),abs(z2))<=500','greatest(abs(x1),abs(x2),abs(z1),abs(z2))<=public.city3b_map_half(c.city)');
  if signature='nexus_city_plan_terrain(uuid,jsonb,jsonb)' then
   body:=replace(replace(body,'< -500','< -public.city3b_map_half(c.city)'),'>500','>public.city3b_map_half(c.city)');
   body:=replace(body,'jsonb_array_length(p_features)>128','jsonb_array_length(p_features)>256');
   body:=replace(body,'when k=''lake'' then 40 when k in (''river'',''garden'') then 12','when k in (''lake'',''river'') then 40 when k=''garden'' then 12');
  end if;
  if before=body then raise exception 'Unexpected spatial function: %',signature;end if;
  execute body;
 end loop;
end $spatial$;

