create function public.nexus_city_create_map(p_user uuid,p_name text,p_country text,p_map text default 'plains') returns uuid language plpgsql security invoker set search_path='' as $$
declare cid uuid;settings jsonb;
begin
 settings:=public.city3b_starting_map(p_map);if settings is null then raise exception 'Carte de départ invalide';end if;
 -- Serialize map creation and retry before the legacy creation function grants rewards.
 perform 1 from public.member_profiles where user_id=p_user and passport_state='active' for update;
 if not found then raise exception 'Passeport 3B actif requis';end if;
 select city_id into cid from public.nexus_cities where user_id=p_user for update;
 if cid is not null then return cid;end if;
 cid:=public.nexus_city_create(p_user,p_name,p_country);
 update public.nexus_cities set city=city||settings,revision=revision+1,updated_at=now() where city_id=cid;
 return cid;
end $$;
revoke all on function public.nexus_city_create_map(uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.nexus_city_create_map(uuid,text,text,text) to service_role;
commit;
